#!/bin/sh
# Snapserver with test tones for netsim runs, in the foreground.
#
#   test/netsim/testserver.sh BUFFER_MS
#
# Streams (440 Hz left, 660 Hz right, generated by ffmpeg):
#   flac44  FLAC 44.1 kHz 16 bit     flac48  FLAC 48 kHz 16 bit
#   opus    Opus 48 kHz              pcm     PCM 44.1 kHz 16 bit
# and pink noise for test/sync/sync.py (right = left delayed by exactly 1 s, so
# FLAC can't exploit the channels' similarity and compresses it like music, and
# either channel of a board can be compared with either channel of another):
#   noise44 FLAC 44.1 kHz 16 bit
# and a silent one: idle (a pipe nobody writes to). A client on it stops
# playing, e.g. to trigger what the client defers until playback stops.
#
# The server is not announced via mDNS (no D-Bus, so no Avahi), so boards only
# reach it through the address you give them. The server buffer is fixed at
# start; restart with another BUFFER_MS to change it.
#
# Needs snapserver and ffmpeg. Environment:
#   NETSIM_DIR   config and server state (default /tmp/netsim-server)
#   STREAM_PORT  audio port (default 1704), TCP_PORT JSON-RPC over TCP (1705),
#   HTTP_PORT    JSON-RPC over HTTP (1780)

set -eu

self=$(readlink -f "$0")

# Called by snapserver as the stream source: raw PCM to stdout.
case ${1:-} in
--tone=*)
    rate=${1#--tone=}
    exec ffmpeg -hide_banner -loglevel error \
        -f lavfi -i "sine=frequency=440:sample_rate=$rate" \
        -f lavfi -i "sine=frequency=660:sample_rate=$rate" \
        -filter_complex "[0:a][1:a]join=inputs=2:channel_layout=stereo" \
        -f s16le -ar "$rate" -ac 2 -
    ;;
--noise=*)
    rate=${1#--noise=}
    exec ffmpeg -hide_banner -loglevel error \
        -f lavfi -i "anoisesrc=color=pink:amplitude=0.2:seed=1:sample_rate=$rate" \
        -filter_complex "[0:a]asplit[l][r];[r]adelay=delays=${rate}S[rd];[l][rd]join=inputs=2:channel_layout=stereo" \
        -f s16le -ar "$rate" -ac 2 -
    ;;
''|-*)
    echo "usage: $0 BUFFER_MS" >&2
    exit 2
    ;;
esac

buf=$1
dir=${NETSIM_DIR:-/tmp/netsim-server}
mkdir -p "$dir/data"

cat > "$dir/snapserver.conf" <<EOF
[server]
datadir = $dir/data
[http]
enabled = true
bind_to_address = 0.0.0.0
port = ${HTTP_PORT:-1780}
doc_root =
[tcp]
enabled = true
port = ${TCP_PORT:-1705}
[stream]
port = ${STREAM_PORT:-1704}
buffer = $buf
source = process://$self?name=flac44&params=--tone=44100&sampleformat=44100:16:2&codec=flac
source = process://$self?name=flac48&params=--tone=48000&sampleformat=48000:16:2&codec=flac
source = process://$self?name=opus&params=--tone=48000&sampleformat=48000:16:2&codec=opus
source = process://$self?name=pcm&params=--tone=44100&sampleformat=44100:16:2&codec=pcm
source = process://$self?name=noise44&params=--noise=44100&sampleformat=44100:16:2&codec=flac
source = pipe://$dir/idle.fifo?name=idle&mode=create&sampleformat=48000:16:2&codec=flac
[logging]
filter = *:info
EOF

echo "snapserver: buffer $buf ms, streams flac44 flac48 opus pcm noise44 idle, config $dir/snapserver.conf"
DBUS_SYSTEM_BUS_ADDRESS=unix:path=/nonexistent exec snapserver -c "$dir/snapserver.conf"
